import {metricDefinitions,metricValue} from './actuator-logic.js?v=0.2.2-cm20261103-r2';
export function countedOptions(records,key='brand'){const counts=new Map();for(const p of records){const v=p[key];counts.set(v,(counts.get(v)||0)+1);}return [...counts].map(([value,count])=>({value,count})).sort((a,b)=>b.count-a.count||a.value.localeCompare(b.value,'en'));}
export const plotAxes={...metricDefinitions,ratedSpecificTorque:['额定扭矩 / 质量','N·m/kg'],peakSpecificTorque:['峰值扭矩 / 质量','N·m/kg']};
export const defaultPlotOptions={x:'massKg',y:'ratedTorque',xScale:'linear',yScale:'linear',colorBy:'brand',layer:'output',labels:false};
export function normalizePlotOptions(raw={}){raw=raw&&typeof raw==='object'?raw:{};const out={...defaultPlotOptions};for(const key of ['x','y'])if(Object.hasOwn(plotAxes,raw[key]))out[key]=raw[key];for(const key of ['xScale','yScale'])if(['linear','log'].includes(raw[key]))out[key]=raw[key];if(['brand','category','encoder'].includes(raw.colorBy))out.colorBy=raw.colorBy;if(['output','module','geared','motor','all'].includes(raw.layer))out.layer=raw.layer;out.labels=raw.labels===true;return out;}
export function normalizeFavorites(raw,validIds){const values=Array.isArray(raw)?raw:[];const valid=new Set(validIds);return [...new Set(values.filter(x=>typeof x==='string'&&valid.has(x)))];}
export function axisMetric(p,key){
 if(!Object.hasOwn(plotAxes,key))return null;
 const numerator={ratedSpecificTorque:'ratedTorque',peakSpecificTorque:'peakTorque'}[key];
 if(numerator){const a=p.metrics?.[numerator],mass=p.metrics?.massKg;if(!Number.isFinite(a?.value)||!Number.isFinite(mass?.value)||mass.value<=0)return null;return {value:a.value/mass.value,unit:'N·m/kg',qual:a.qual||mass.qual?'derived':'',derived:true,conditions:[a.condition,mass.condition].filter(Boolean),sourceIds:[a.source,mass.source].filter(Boolean),inputs:[numerator,'massKg']};}
 const m=p.metrics?.[key];if(!Number.isFinite(m?.value))return null;return {...m,conditions:[m.condition].filter(Boolean),sourceIds:[m.source].filter(Boolean),inputs:[key]};
}
export function buildPlotData(records,rawOptions={}){const options=normalizePlotOptions(rawOptions),points=[],excluded=[];for(const product of records){if(options.layer!=='all'&&(options.layer==='output'?!['module','geared'].includes(product.integration||'module'):(product.integration||'module')!==options.layer)){excluded.push({id:product.id,reason:'layer'});continue;}const x=axisMetric(product,options.x),y=axisMetric(product,options.y);if(!x||!y){excluded.push({id:product.id,reason:'missing'});continue;}if(options.xScale==='log'&&x.value<=0||options.yScale==='log'&&y.value<=0){excluded.push({id:product.id,reason:'nonPositive'});continue;}points.push({id:product.id,product,x,y});}return {options,points,excluded,counts:{input:records.length,plotted:points.length,layer:excluded.filter(x=>x.reason==='layer').length,missing:excluded.filter(x=>x.reason==='missing').length,nonPositive:excluded.filter(x=>x.reason==='nonPositive').length}};}
function niceStep(span,count=5){const raw=span/count,power=10**Math.floor(Math.log10(raw)),fraction=raw/power;return ([1,2,2.5,5,10].find(n=>n>=fraction)||10)*power;}
export function axisDomain(values,scale='linear'){const usable=values.filter(x=>Number.isFinite(x)&&(scale!=='log'||x>0));if(!usable.length)return scale==='log'?[0.1,10]:[0,1];const min=Math.min(...usable),max=Math.max(...usable);if(scale==='log'){if(min===max)return [min/2,max*2];const pad=(Math.log10(max)-Math.log10(min))*.08;return [10**(Math.log10(min)-pad),10**(Math.log10(max)+pad)];}const low=Math.min(0,min),high=max>0?max*1.08:1,step=niceStep(high-low);return [low,Math.ceil(high/step)*step];}
export function scaleValue(value,domain,range,scale='linear'){if(!Number.isFinite(value)||scale==='log'&&value<=0)return null;const transform=scale==='log'?Math.log10:x=>x;const a=transform(domain[0]),b=transform(domain[1]);return range[0]+(transform(value)-a)/(b-a)*(range[1]-range[0]);}
export function axisTicks(domain,scale='linear',count=5){if(scale==='log'){const ticks=[];for(let p=Math.ceil(Math.log10(domain[0]));p<=Math.floor(Math.log10(domain[1]));p++)ticks.push(10**p);return ticks.length>=2?ticks:Array.from({length:count},(_,i)=>10**(Math.log10(domain[0])+i/(count-1)*(Math.log10(domain[1])-Math.log10(domain[0]))));}const step=niceStep(domain[1]-domain[0],count),first=Math.ceil(domain[0]/step)*step,ticks=[];for(let i=0;i<100;i++){const v=first+i*step;if(v>domain[1]+step*1e-8)break;ticks.push(v);}return ticks;}
export function plotCsv(plot,sources={}){const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const {options}=plot;const rows=[['ID','厂商','型号','集成层级',...['x','y'].flatMap(axis=>[axis+' metric',axis+' value',axis+' unit',axis+' qualifier',axis+' original conditions',axis+' sources'])]];for(const point of plot.points)rows.push([point.id,point.product.brand,point.product.model,point.product.integration||'module',...['x','y'].flatMap(axis=>{const m=point[axis];return [options[axis],m.value,m.unit||plotAxes[options[axis]][1],m.qual||'',m.conditions.join(' | '),m.sourceIds.map(id=>sources[id]?.url||id).join(' | ')];})]);return '\uFEFF'+rows.map(row=>row.map(safe).join(',')).join('\r\n');}
